// ─── Large synthetic dataset for virtual-scroll stress test ───────────────────
const SERVICES = [
  'user-service', 'payment-service', 'frontend-app', 'api-gateway', 'db-service',
  'auth-service', 'analytics-service', 'cache-service', 'profile-service',
  'order-service', 'notification-service', 'image-processor', 'feature-service',
  'checkout-service', 'worker-service', 'infra-service', 'monitoring-service',
  'deploy-service',
];
const PLATFORMS   = ['web', 'nodejs', 'mobile'];
const SEVERITIES  = ['critical', 'critical', 'warning', 'warning', 'warning', 'info'];
const ENVS        = ['production', 'staging', 'development'];
const MESSAGES = [
  'TypeError: Cannot read properties of undefined (reading "map")',
  'ReferenceError: fetch is not defined',
  'SyntaxError: Unexpected token < in JSON at position 0',
  'NetworkError: Failed to fetch /api/v2/users',
  'UnhandledPromiseRejection: Database connection timeout',
  'RangeError: Maximum call stack size exceeded',
  'Warning: Memory usage exceeded 80% threshold',
  'ChunkLoadError: Loading chunk failed',
  'AuthError: JWT signature verification failed',
  'CORS policy blocked request from origin',
  'DatabaseError: Deadlock detected, transaction rolled back',
  'SocketError: Connection closed unexpectedly (code: 1006)',
  'ValidationError: Invalid email format in registration payload',
  'HeapOutOfMemoryError: JS heap out of memory',
  'RateLimitError: Too many requests, retry after 60s',
  'NullPointerException in controller',
  'Memory leak detected in worker thread',
  'Slow query detected: execution time exceeded',
  'API response time exceeded threshold',
  'Cache miss rate above 60%',
  'SSL certificate expires soon',
  'Stack overflow in recursive function',
  'Disk usage critical on production server',
  'Failed to parse malformed JSON response',
  'Uncaught TypeError in checkout flow',
];

function seededRand(n, seed) {
  // Simple deterministic pseudo-random based on index
  return ((seed * 1103515245 + 12345) & 0x7fffffff) % n;
}

export function generateLargeDataset(count = 10000) {
  const base = new Date('2026-06-01T00:00:00Z').getTime();
  const results = [];
  for (let i = 0; i < count; i++) {
    const s1 = seededRand(SERVICES.length, i * 7 + 1);
    const s2 = seededRand(PLATFORMS.length, i * 13 + 3);
    const s3 = seededRand(SEVERITIES.length, i * 17 + 5);
    const s4 = seededRand(ENVS.length, i * 11 + 7);
    const s5 = seededRand(MESSAGES.length, i * 19 + 9);
    results.push({
      id: `gen-${i + 1}`,
      message: MESSAGES[s5],
      service: SERVICES[s1],
      platform: PLATFORMS[s2],
      severity: SEVERITIES[s3],
      environment: ENVS[s4],
      timestamp: new Date(base + i * 12000).toISOString(), // every 12s
      count: ((i * 37 + 11) % 500) + 1,
      resolved: i % 7 === 0,
    });
  }
  return results;
}

